-- Tasks (CM-0019 §2–§5).
ALTER TABLE "construction_tracking"."task_counters" ADD CONSTRAINT "task_counters_last_no_check" CHECK ("last_no" >= 0);
ALTER TABLE "construction_tracking"."tasks" ADD CONSTRAINT "tasks_figures_check" CHECK (
  "task_no" > 0
  AND "depth" BETWEEN 1 AND 3
  AND (("parent_id" IS NULL) = ("depth" = 1))
  AND length(btrim("name")) > 0
  AND ("start_date" IS NULL OR "due_date" IS NULL OR "due_date" >= "start_date")
  AND ("baseline_start" IS NULL) = ("baseline_end" IS NULL)
  AND ("baseline_end" IS NULL OR "baseline_end" >= "baseline_start")
  AND ("total_work_qty" IS NULL OR "total_work_qty" > 0)
  AND ("total_work_qty" IS NULL) = ("total_work_unit_id" IS NULL)
  AND ("total_price" IS NULL OR "total_price" >= 0)
  AND "completed_work_qty" >= 0
  AND "progress_pct" BETWEEN 0 AND 100
  AND ("actual_end" IS NULL OR "actual_start" IS NULL OR "actual_end" >= "actual_start")
);
ALTER TABLE "construction_tracking"."task_baselines" ADD CONSTRAINT "task_baselines_figures_check" CHECK ("version" > 0 AND "end_date" >= "start_date");
-- A progress update carries a quantity or a percentage, never both; worksheet
-- updates name their worksheet.
ALTER TABLE "construction_tracking"."task_progress" ADD CONSTRAINT "task_progress_figures_check" CHECK (
  (("work_qty" IS NULL) <> ("progress_pct" IS NULL))
  AND ("work_qty" IS NULL OR "work_qty" > 0)
  AND ("progress_pct" IS NULL OR "progress_pct" BETWEEN 0 AND 100)
  AND (("source" = 'worksheet') = ("worksheet_id" IS NOT NULL))
);
-- One live update per worksheet.
CREATE UNIQUE INDEX "task_progress_live_worksheet_key" ON "construction_tracking"."task_progress"("worksheet_id") WHERE "deleted_at" IS NULL AND "worksheet_id" IS NOT NULL;

-- Issues & Snags (CM-0019 §7, §8).
ALTER TABLE "construction_tracking"."issues" ADD CONSTRAINT "issues_figures_check" CHECK (
  length(btrim("details")) > 0
  AND ("due_date" IS NULL OR "due_date" >= "issue_date")
  AND (("status" = 'open') OR ("solved_at" IS NOT NULL AND "solved_by" IS NOT NULL))
  AND (("status" = 'closed') = ("closed_at" IS NOT NULL))
);
ALTER TABLE "construction_tracking"."issue_updates" ADD CONSTRAINT "issue_updates_body_check" CHECK ("body" IS NULL OR length(btrim("body")) > 0);

-- Inspection Requests (CM-0019 §9, §10).
ALTER TABLE "construction_tracking"."inspections" ADD CONSTRAINT "inspections_figures_check" CHECK (
  length(btrim("work_description")) > 0
  AND ("inspection_time" IS NULL OR "inspection_time" ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$')
  AND (("status" = 'pending') = ("decided_at" IS NULL))
  AND (("status" = 'pending') = ("decided_by" IS NULL))
  AND (("status" = 'rejected') = ("rejection_reason" IS NOT NULL))
  AND ("reinspection_of_id" IS NULL OR "reinspection_of_id" <> "id")
);
ALTER TABLE "construction_tracking"."inspection_observations" ADD CONSTRAINT "inspection_observations_body_check" CHECK ("body" IS NULL OR length(btrim("body")) > 0);
ALTER TABLE "construction_tracking"."inspection_remarks" ADD CONSTRAINT "inspection_remarks_body_check" CHECK (length(btrim("body")) > 0);

-- Files.
ALTER TABLE "construction_tracking"."document_files" ADD CONSTRAINT "document_files_bytes_check" CHECK ("bytes" >= 0);
